from pathlib import Path
import hashlib,json,subprocess,datetime

ROOT=Path('/workspace/rutcampustrack')
OUT=Path(__file__).parent
entries=[]
def add(id,path,status,needles,note):
    p=ROOT/path
    raw=p.read_bytes()
    lines=raw.decode('utf-8-sig').splitlines()
    fragments=[{'line':i,'text':line} for i,line in enumerate(lines,1) if any(n in line for n in needles)]
    assert fragments,(id,path)
    entries.append({'source_id':id,'canonical_path':path,'sha256':hashlib.sha256(raw).hexdigest(),'status':status,'fragments':fragments,'bounded_claim':note,'read_scope':'Exact selected original fragments and relevant surrounding code, not claim of full source-family acceptance'})

